# -*- coding: utf-8 -*-
"""MD Wines fanpage generator: 24 kieu cover + 5 kieu noi dung + 2 CTA. Xuat PNG/JPG 1080x1350."""
import sys,os,re,html,json,hashlib,glob
sys.path.insert(0,'/tmp/rep/blogbuild')
from content import ARTICLES
A='file:///home/claude/mdwines.vn/assets/'
LOGO=A+'media/mdwines-gold-logo-new_03006611_hq.webp'
BOT={'cab':'bottle-cab','shi':'bottle-shi','90':'bottle-90','qui':'bottle-qui','77':'bottle-77','ghe':'bottle-ghe'}
def esc(t): return html.escape(t,quote=True)
def strip(h): return re.sub(r'<[^>]+>','',h)
POOL=sorted(glob.glob('/home/claude/mdwines.vn/assets/blog/*.jpg'))
POOL=['file://'+p for p in POOL if 'og-' not in p]
def hero(a):
    i=a['img']
    if i.startswith('@'):
        h=int(hashlib.md5(a['slug'].encode()).hexdigest(),16);return POOL[h%len(POOL)]
    return A+'blog/%s.jpg'%i
def pool(a,k):
    h=int(hashlib.md5((a['slug']+str(k)).encode()).hexdigest(),16);return POOL[h%len(POOL)]
def fs(t,big,small,n1=26,n2=70):
    L=len(t);
    if L<=n1: return big
    if L>=n2: return small
    return int(big-(big-small)*(L-n1)/(n2-n1))
def trunc(t,n):
    t=re.sub(r'\s+',' ',strip(t)).strip()
    if len(t)<=n: return t
    c=t[:n];k=max(c.rfind('. '),c.rfind('; '),c.rfind(', '))
    return (c[:k] if k>n*.5 else c[:c.rfind(' ')]).rstrip(' ,;.')+'…'
HEAD='<!doctype html><meta charset=utf-8><link rel=stylesheet href="file:///tmp/fb/style.css"><style>.logo{object-fit:contain}.eb{letter-spacing:.3em;text-transform:uppercase;color:#e8c66d;font-weight:600}.fr{position:absolute;inset:36px;border:2px solid #e8c66d99;pointer-events:none}.fr:after{content:"";position:absolute;inset:10px;border:1px solid #e8c66d44}.abs{position:absolute}</style>'
def W(body,css=''): return HEAD+'<style>'+css+'</style>'+body
