COUNTS=[3,5,1,7,4,9,2,6,8,10]
def slides_for(a,idx,n=None):
    n=n or COUNTS[idx%len(COUNTS)]
    cover=COVERS[idx%len(COVERS)](a)
    out=[('cover',cover)]
    if n==1: return out
    if n==2: return out+[('cta',cta(a,idx%2))]
    mids=n-2;secs=len(a['body']);res=[]
    for m in range(mids):
        if m<secs: res.append(('ct',ct(a,m+2,n,m,(idx+m)%5)))
        else: res.append(('photo',photo_slide(a,m+2,n,m)))
    return out+res+[('cta',cta(a,(idx+1)%2))]
