TAGS={'Quà tặng':'#ruouvang #quatang #quatet','Kiến thức':'#ruouvang #kienthucruouvang','Mua rượu vang':'#muaruouvang #ruouvangnhapkhau','Vùng nho & sản phẩm':'#ruouvangUc #vungnho','Thương hiệu':'#MDWines #ruouvangUc','Thưởng thức & ẩm thực':'#thuongthucvang #amthuc','Bảo quản & sử dụng':'#baoquanruouvang'}
def _clean(t):
    import re as _r
    t=_r.sub(r'</(td|th)>',' · ',t);t=_r.sub(r'</(li|tr)>','. ',t);t=_r.sub(r'<[^>]+>',' ',t)
    t=' '.join(t.split());t=t.replace(' · .','.').replace(' .','.').replace('. .','.').replace('..','.')
    return t
def _sent(t,n):
    import re as _r
    t=_clean(t)
    if len(t)<=n: return t
    c=t[:n];k=max(c.rfind('. '),c.rfind('! '),c.rfind('? '))
    return c[:k+1] if k>n*0.5 else c.rsplit(' ',1)[0]+'…'
def caption(a):
    _g=lambda p:any(p[i].islower() and p[i+1].isupper() for i in range(len(p)-1))
    _ld=a['lead']
    out=[a['title'].upper(),'',_sent(_ld,420)]
    for h,ps in a['body'][:5]:
        import re as _q
        ps=[p for p in ps if len(p)>40 and '<table' not in p][:2]
        if not ps or _g(h) or len(h)>90: continue
        out+=['','✦ '+h,_sent(ps[0],330)]
        if len(ps)>1 and len("\n".join(out))<1900: out.append(_sent(ps[1],260))
    link='https://mdwines.vn/tin-tuc/%s/'%a['slug']
    out+=['','Bạn thấy chai nào hợp với khoảnh khắc của mình? Để lại bình luận hoặc nhắn MD Wines để được tư vấn chọn chai.','','▶ Đọc bài đầy đủ: '+link,'',FOOT,'','#MDWines '+TAGS.get(a['cat'],'#ruouvang')]
    return "\n".join(out)
if __name__=='__main__':
    from playwright.sync_api import sync_playwright
    which=sys.argv[1]; out=sys.argv[2]
    idxs=[int(x) for x in which.split(',')]
    os.makedirs(out,exist_ok=True);meta=[]
    with sync_playwright() as p:
        b=p.chromium.launch(args=['--allow-file-access-from-files']);pg=b.new_page(viewport={'width':1080,'height':1350})
        for idx in idxs:
            a=ARTICLES[idx%len(ARTICLES)];sl=slides_for(a,idx)
            files=[]
            for j,(kind,h) in enumerate(sl):
                fn=f'{out}/p{idx:02d}-{j+1:02d}-{kind}.html';open(fn,'w',encoding='utf-8').write(h)
                pg.goto('file://'+fn);pg.wait_for_timeout(500)
                png=f'{out}/p{idx:02d}-{j+1:02d}-{kind}.jpg';pg.screenshot(path=png,type='jpeg',quality=90);files.append(png)
            meta.append({'idx':idx,'slug':a['slug'],'cat':a['cat'],'caption':caption(a),'images':files})
        b.close()
    json.dump(meta,open(out+'/meta.json','w'),ensure_ascii=False,indent=1);print('ok',len(meta))
